def verify(solution):
    N = len(solution)
    # Check rows (implicitly fine)
    # Check columns
    if len(set(solution)) != N:
        return False, "Column conflict"
    # Check diagonals
    for i in range(N):
        for j in range(i+1, N):
            if abs(i - j) == abs(solution[i] - solution[j]):
                return False, f"Diagonal conflict between rows {i} and {j}"
    return True, "Valid"

sol = [2, 0, 7, 10, 4, 9, 1, 13, 11, 6, 8, 12, 5, 3]
print(verify(sol))
print(f"q[4] = {sol[4]}, q[6] = {sol[6]}")
